import { memo } from "react";
import {
  ProceduralBackground,
  type ProceduralBackgroundProps,
} from "./procedural-background.shared";

export interface ChromaBackgroundProps extends ProceduralBackgroundProps {
  hueShift?: number;
  grain?: number;
}

export const ChromaBackground = memo(function ChromaBackground({
  hueShift = 0,
  grain = 0.035,
  ...props
}: ChromaBackgroundProps = {}) {
  const hue = Number.isFinite(hueShift) ? (hueShift * Math.PI) / 180 : 0;
  const texture = Number.isFinite(grain) ? Math.max(0, Math.min(0.2, grain)) : 0.035;
  return <ProceduralBackground {...props} variant="chroma" settings={[hue, texture]} />;
});

"use client";

import { memo, type ComponentProps } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion, useSpring } from "motion/react";
import { Canvas } from "./canvas";
import chromaShader from "./chroma-background.wgsl";
import asciiShader from "./ascii-background.wgsl";
import heatmapShader from "./heatmap-background.wgsl";
import liquidChromeShader from "./liquid-chrome-background.wgsl";

const shaders = {
  chroma: chromaShader,
  ascii: asciiShader,
  heatmap: heatmapShader,
  "liquid-chrome": liquidChromeShader,
};
const fallbacks = {
  "liquid-chrome":
    "linear-gradient(125deg, #080a0e 5%, #818995 20%, #eef3fa 24%, #161a23 31%, #444d5c 55%, #e6edf7 61%, #11151c 69%, #6a7484 85%, #11151b)",
  chroma:
    "radial-gradient(ellipse at 20% 30%, #482171, transparent 65%), radial-gradient(ellipse at 80% 70%, #075364, transparent 65%), linear-gradient(135deg, #160d25, #0c1533)",
  ascii: "linear-gradient(135deg, #03130c, #0a2c20, #03130c)",
  heatmap:
    "radial-gradient(ellipse at 40% 35%, #f64b17, #f7c522 20%, #0c997c 45%, #183497 70%, #080c31)",
};

const lightFallbacks = {
  "liquid-chrome":
    "linear-gradient(125deg, #bdcad8, #f8fafc 24%, #283949 32%, #dbe5ee 60%, #f8fafc 80%)",
  chroma:
    "radial-gradient(ellipse at 20% 30%, #d7c4ef, transparent 65%), radial-gradient(ellipse at 80% 70%, #b3e5eb, transparent 65%), linear-gradient(135deg, #f7edf9, #e5ecf7)",
  ascii: "linear-gradient(135deg, #e8f5ed, #c3dfd0, #edf7f0)",
  heatmap: "linear-gradient(135deg, #c6d6f1, #6bd8ff, #ffe77a, #ff9a1f, #ff4d00)",
};

export interface ProceduralBackgroundProps extends ComponentProps<"div"> {
  speed?: number;
  interactive?: boolean;
  intensity?: number;
}

export const ProceduralBackground = memo(function ProceduralBackground({
  variant,
  settings,
  palette,
  fallback,
  lightFallback,
  speed = 0.2,
  intensity = 0.9,
  interactive = true,
  onPointerMove,
  onPointerLeave,
  onPointerCancel,
  ...props
}: ProceduralBackgroundProps & {
  variant: keyof typeof shaders;
  settings: readonly [number, number, number?, number?];
  palette?: Record<string, number[]>;
  fallback?: string;
  lightFallback?: string;
}) {
  const reducedMotion = useReducedMotion();
  const x = useSpring(0.5, { stiffness: 100, damping: 22 });
  const y = useSpring(0.5, { stiffness: 100, damping: 22 });
  const hover = useSpring(0, { stiffness: 180, damping: 24 });
  const rate = Number.isFinite(speed) ? Math.max(0, speed) : 0.2;
  const brightness = Number.isFinite(intensity) ? Math.max(0, Math.min(2, intensity)) : 0.9;
  const leave = () => {
    hover.set(0);
    x.set(0.5);
    y.set(0.5);
  };
  return (
    <Canvas
      {...props}
      shader={shaders[variant]}
      label={`${variant}-background`}
      lightFallback={lightFallback ?? lightFallbacks[variant]}
      fallback={fallback ?? fallbacks[variant]}
      fallbackContent={
        variant === "ascii" ? (
          <pre className="absolute inset-0 overflow-hidden whitespace-pre-wrap p-4 font-mono text-xs leading-4 text-emerald-400/25">
            {" .:-=+*#%@   .::--===+++***##%%@@  ".repeat(250)}
          </pre>
        ) : variant === "chroma" ? (
          <motion.div
            aria-hidden="true"
            className="absolute inset-[-20%]"
            style={{
              backgroundImage:
                "radial-gradient(ellipse at 18% 30%, #e73cff 0%, transparent 42%), radial-gradient(ellipse at 78% 24%, #00d9ff 0%, transparent 45%), radial-gradient(ellipse at 72% 78%, #00ff9d 0%, transparent 42%), linear-gradient(135deg, #160d25, #0c1533)",
              backgroundSize: "145% 145%",
            }}
            animate={
              reducedMotion
                ? undefined
                : { x: ["-8%", "8%", "-8%"], y: ["5%", "-5%", "5%"], rotate: [0, 4, 0] }
            }
            transition={
              reducedMotion ? undefined : { duration: 7, repeat: Infinity, ease: "easeInOut" }
            }
          />
        ) : undefined
      }
      animated={rate > 0 || interactive}
      fps={variant === "liquid-chrome" ? 60 : 30}
      dpr={variant === "liquid-chrome" ? [1, 1.5] : 1}
      uniforms={(time, size) => ({
        ...(variant === "heatmap" ? { palette } : {}),
        cfg: {
          metrics: [size[0], size[1], time * rate, brightness],
          pointer: [x.get(), y.get(), interactive && !reducedMotion ? hover.get() : 0, 0],
          settings: [settings[0], settings[1], settings[2] ?? 0, settings[3] ?? 0],
        },
      })}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        if (
          event.defaultPrevented ||
          !interactive ||
          reducedMotion ||
          event.pointerType === "touch"
        )
          return;
        const bounds = event.currentTarget.getBoundingClientRect();
        if (!bounds.width || !bounds.height) return;
        x.set(Math.max(0, Math.min(1, (event.clientX - bounds.left) / bounds.width)));
        y.set(Math.max(0, Math.min(1, (event.clientY - bounds.top) / bounds.height)));
        hover.set(1);
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        leave();
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        leave();
      }}
    />
  );
});

import { lightCyan, lightPaper, lightRose, lightViolet } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  metrics: vec4f, // width, height, time, intensity
  pointer: vec4f, // normalized position, hover strength, reserved
  settings: vec4f, // hue offset in radians, grain strength, reserved
};
@group(0) @binding(0) var<uniform> cfg: Config;

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let aspect = cfg.metrics.x / cfg.metrics.y;
  var p = (uv - 0.5) * vec2f(aspect, 1.0) * 2.0;
  let cursor = (uv - cfg.pointer.xy) * vec2f(aspect, 1.0);
  let influence = exp(-dot(cursor, cursor) * 5.0) * cfg.pointer.z;
  p += cursor * influence * 0.45;
  let time = cfg.metrics.z;
  let warpA = vec2f(
    sin(p.y * 2.2 + time * 0.55) + cos(p.x * 1.3 - time * 0.35),
    cos(p.x * 2.0 - time * 0.5) + sin(p.y * 1.5 + time * 0.4)
  );
  let q = p + warpA * 0.42;
  let warpB = vec2f(
    sin(q.y * 4.5 - time * 0.8),
    cos(q.x * 4.0 + time * 0.65)
  );
  let r = q + warpB * 0.12;
  let flow = sin(r.x * 2.4 + r.y * 1.7 + time * 0.45) +
    cos(r.y * 2.8 - r.x * 1.2 - time * 0.32);
  let bands = 0.5 + 0.5 * sin(flow * 3.0 + r.x * 1.8 + time * 0.25);
  let phase = flow * 1.7 + bands * 1.2 + cfg.settings.x;
  let spectrum = 0.5 + 0.5 * cos(vec3f(0.0, 2.094, 4.188) + phase);
  let ribbons = smoothstep(0.18, 0.82, bands);
  let glow = 0.08 + ribbons * 0.82 + influence * 0.16;
  let vignette = 1.0 - smoothstep(0.35, 1.25, length(p)) * 0.5;
  let grain = fract(sin(dot(floor(uv * cfg.metrics.xy), vec2f(12.9898, 78.233))) * 43758.5453) - 0.5;
  if (theme.mode.x > 0.5) {
    let dye = (lightRose() * spectrum.r + lightCyan() * spectrum.g + lightViolet() * spectrum.b) / max(spectrum.r + spectrum.g + spectrum.b, 0.001);
    let pigment = mix(lightPaper(), dye, glow * vignette * 0.78 * cfg.metrics.w);
    return vec4f(pigment + vec3f(grain * cfg.settings.y * 0.3), 1.0);
  }
  var color = vec3f(0.008, 0.006, 0.02) + pow(max(spectrum, vec3f(0.0)), vec3f(1.25)) * glow * vignette * cfg.metrics.w;
  color += vec3f(grain * cfg.settings.y);
  return vec4f(clamp(color, vec3f(0), vec3f(1)), 1.0);
}

import { lightEmerald, lightInk, lightPaper } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config { metrics: vec4f, pointer: vec4f, settings: vec4f };
@group(0) @binding(0) var<uniform> cfg: Config;

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let cellSize = cfg.settings.x;
  let grid = uv * cfg.metrics.xy / cellSize;
  let cell = floor(grid);
  let point = (cell + 0.5) * cellSize / cfg.metrics.y;
  let time = cfg.metrics.z;
  let field = sin(point.x * 3.2 + time) * cos(point.y * 3.8 - time * 0.7)
    + sin((point.x + point.y) * 2.4 - time * 0.5) * 0.5;
  let delta = (cell + 0.5) * cellSize - cfg.pointer.xy * cfg.metrics.xy;
  let hover = exp(-dot(delta, delta) / 18000.0) * cfg.pointer.z;
  let brightness = clamp(0.4 + field * 0.3 + hover * 0.45, 0.0, 1.0);
  let character = u32(brightness * 9.0);
  let glyphs = array<u32, 10>(0u, 131072u, 131200u, 31744u, 1016800u, 4357252u, 22511061u, 11512810u, 27070835u, 32175662u);
  let local = vec2i(floor(fract(grid) * 7.0)) - vec2i(1);
  var ink = 0.0;
  if (all(local >= vec2i(0)) && all(local < vec2i(5))) {
    ink = f32((glyphs[character] >> u32(local.y * 5 + local.x)) & 1u);
  }
  if (theme.mode.x > 0.5) {
    let paper = lightPaper();
    let inkColor = mix(lightInk(), lightEmerald(), brightness);
    return vec4f(mix(paper, inkColor, ink * clamp((0.9 + brightness * 0.1) * cfg.metrics.w, 0.0, 1.0)), 1.0);
  }
  let tint = mix(vec3f(0.08, 0.55, 0.35), vec3f(0.55, 1.0, 0.85), brightness);
  return vec4f(vec3f(0.005, 0.012, 0.01) + tint * ink * (0.3 + brightness * 0.7) * cfg.metrics.w, 1.0);
}

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config { metrics: vec4f, pointer: vec4f, settings: vec4f };
@group(0) @binding(0) var<uniform> cfg: Config;

struct Palette { color0: vec4f, color1: vec4f, color2: vec4f, color3: vec4f, color4: vec4f, color5: vec4f, color6: vec4f, lightColor0: vec4f, lightColor1: vec4f, lightColor2: vec4f, lightColor3: vec4f, lightColor4: vec4f, lightColor5: vec4f, lightColor6: vec4f };
@group(0) @binding(1) var<uniform> palette: Palette;

fn thermal(value: f32) -> vec3f {
  let t = clamp(value, 0.0, 1.0) * 6.0;
  let colors = array<vec3f, 7>(palette.color0.rgb, palette.color1.rgb, palette.color2.rgb,
    palette.color3.rgb, palette.color4.rgb, palette.color5.rgb, palette.color6.rgb);
  let index = min(u32(t), 5u);
  let blend = smoothstep(0.0, 1.0, t - f32(index));
  if (theme.mode.x > 0.5) {
    let lightColors = array<vec3f, 7>(palette.lightColor0.rgb, palette.lightColor1.rgb, palette.lightColor2.rgb,
      palette.lightColor3.rgb, palette.lightColor4.rgb, palette.lightColor5.rgb, palette.lightColor6.rgb);
    return mix(lightColors[index], lightColors[index + 1u], blend);
  }
  return mix(colors[index], colors[index + 1u], blend);
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let aspect = cfg.metrics.x / cfg.metrics.y;
  let p = (uv - 0.5) * vec2f(aspect, 1.0) * cfg.settings.x;
  let time = cfg.metrics.z;
  let warmCenter = vec2f(sin(time * 0.55) * 0.42, cos(time * 0.38) * 0.32);
  let warmCenter2 = vec2f(cos(time * 0.3 + 1.5) * 0.5, sin(time * 0.48) * 0.3);
  let coldCenter = vec2f(cos(time * 0.32) * 0.5, sin(time * 0.44) * 0.38);
  let warm = exp(-dot(p - warmCenter, p - warmCenter) * 4.5);
  let warm2 = exp(-dot(p - warmCenter2, p - warmCenter2) * 5.0);
  let cool = exp(-dot(p - coldCenter, p - coldCenter) * 3.5);
  let waves = sin(p.x * 3.2 + sin(p.y * 2.6 + time * 0.8)) *
    cos(p.y * 2.8 - time * 0.5);
  let ripples = sin(length(p) * 8.0 - time * 1.2) * 0.08;
  let cursor = (uv - cfg.pointer.xy) * vec2f(aspect, 1.0);
  let heat = exp(-dot(cursor, cursor) * 12.0) * cfg.pointer.z * 0.45;
  let temperature = 0.28 + waves * 0.16 + ripples + warm * 0.55 + warm2 * 0.3 - cool * 0.22 + heat;
  return vec4f(thermal(temperature) * cfg.metrics.w, 1.0);
}

import { lightCyan, lightSurface } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config { metrics: vec4f, pointer: vec4f, settings: vec4f };
@group(0) @binding(0) var<uniform> cfg: Config;

fn softbox(p: vec2f, center: vec2f, size: vec2f, softness: f32) -> f32 {
  let q = abs(p - center) - size;
  let distance = length(max(q, vec2f(0))) + min(max(q.x, q.y), 0.0);
  return 1.0 - smoothstep(-softness, softness, distance);
}

fn studio(reflection: vec3f, blur: f32) -> vec3f {
  let p = reflection.xy / max(reflection.z + 1.0, 0.08);
  let radius = length(p);
  let soft = 0.035 + blur;
  let key = softbox(p, vec2f(-0.25, 0.42), vec2f(0.3, 0.12), soft);
  let side = softbox(p, vec2f(0.48, 0.12), vec2f(0.06, 0.3), soft);
  let ground = softbox(p, vec2f(-0.1, -0.55), vec2f(0.45, 0.06), soft);
  let rim = exp(-pow((radius - 1.0) / (0.05 + blur * 1.5), 2.0));
  let wall = smoothstep(1.2, 1.7, radius) * (0.45 + 0.2 * sin(atan2(p.y, p.x) * 3.0));
  if (theme.mode.x > 0.5) {
    let studioWall = mix(lightSurface(), lightCyan(), 0.12);
    let blackFlag = softbox(p, vec2f(-0.1, 0.1), vec2f(0.07, 0.48), soft * 1.4);
    return studioWall * (1.0 - blackFlag * 0.85) + vec3f(1.0, 0.98, 0.94) * key * 1.4 + vec3f(side * 0.6 + rim * 0.3);
  }
  return vec3f(0.018) + vec3f(1.0, 0.98, 0.96) * key * 2.8
    + vec3f(0.93, 0.97, 1.0) * side * 2.0 + vec3f(ground * 0.8 + rim * 1.1 + wall);
}

fn shade(slope: vec2f, view: vec3f, blur: f32) -> vec3f {
  let steepness = length(slope);
  let limited = slope * (3.0 * tanh(steepness / 3.0) / max(steepness, 0.00001));
  let normal = normalize(vec3f(-limited, 1.0));
  let reflected = reflect(view, normal);
  let facing = clamp(dot(normal, -view), 0.0, 1.0);
  let fresnel = 0.92 + 0.08 * pow(1.0 - facing, 5.0);
  return studio(reflected, blur) * fresnel;
}

fn tonemap(color: vec3f) -> vec3f {
  return clamp((color * (2.51 * color + 0.03)) / (color * (2.43 * color + 0.59) + 0.14), vec3f(0), vec3f(1));
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let aspect = cfg.metrics.x / cfg.metrics.y;
  let original = (uv - 0.5) * vec2f(aspect, 1.0) * cfg.settings.x;
  var p = original;
  var rowX = vec2f(1, 0);
  var rowY = vec2f(0, 1);
  let time = cfg.metrics.z;
  // Carry the warp derivatives forward for a smooth surface normal.
  for (var octave = 1; octave <= 4; octave++) {
    let i = f32(octave);
    let amplitude = cfg.settings.y * 0.3 / i;
    let soften = exp(0.3 - 0.3 * i);
    let x = i * 3.0 * p.y + time;
    p.x += amplitude * cos(x);
    rowX -= amplitude * sin(x) * i * 3.0 * soften * rowY;
    let y = i * 3.0 * p.x + time;
    p.y += amplitude * cos(y);
    rowY -= amplitude * sin(y) * i * 3.0 * soften * rowX;
  }
  let phase = time - p.x - p.y;
  let field = -(rowX + rowY);
  let across = field / max(length(field), 0.0001);
  let sharpness = 1.45;
  let bevel = tanh(sharpness * sin(phase));
  var slope = sharpness * cos(phase) * (1.0 - bevel * bevel) / tanh(sharpness) * across;
  let cursor = (cfg.pointer.xy - 0.5) * vec2f(aspect, 1.0) * cfg.settings.x;
  let delta = original - cursor;
  let distance = length(delta);
  let ripple = exp(-distance * distance * 3.0) * (9.0 * cos(distance * 9.0 - time) - 6.0 * distance * sin(distance * 9.0 - time));
  slope += delta / max(distance, 0.001) * ripple * cfg.pointer.z * 0.1;

  // Integrate across the steepest pixel footprint to soften thin reflections.
  let stepX = dpdx(slope);
  let stepY = dpdy(slope);
  let sweep = select(stepY, stepX, dot(stepX, stepX) > dot(stepY, stepY));
  let blur = cfg.settings.z * 0.35 + length(sweep) * 0.15;
  let view = normalize(vec3f(original * 0.08, -1));
  var light = vec3f(0);
  for (var sample = 0; sample < 4; sample++) {
    let offset = (f32(sample) + 0.5) / 4.0 - 0.5;
    light += shade(slope + sweep * offset, view, blur);
  }
  let color = pow(tonemap(light * 0.25 * cfg.settings.w * cfg.metrics.w), vec3f(1.0 / 2.2));
  return vec4f(color, 1.0);
}

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
